struct AchievementSession::Control {
    mutable std::mutex mutex;
    std::shared_ptr<const ConfigSnapshot> current;
    std::weak_ptr<Pending> pending;
    bool initialized=false,closed=false;
};
struct AchievementSession::Pending {
